namespace LastRail.Tests.EditMode {public sealed partial class FormationLocalHttpTests {
 static RunResultSubmitRequest SavedFixtureFinish(string id){var body=new JObject{["runId"]=id,["encounterType"]="ORDINARY_15_WAVE",["outcome"]="VICTORY",["currentStage"]="Complete",["currentWaveNumber"]=0,["completedWaveCount"]=15,["runtimeStateJson"]=new JObject{["runId"]=id}.ToString(),["tacticSelections"]=new JArray(),["clientCompletedAt"]=DateTime.UtcNow.ToString("yyyy-MM-ddTHH:mm:ss.fffZ")};return (RunResultSubmitRequest)Activator.CreateInstance(typeof(RunResultSubmitRequest),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{id,"fixture_original_finish_key",body.ToString()},null);}
 static async Task PrepareResultFixture(AccountScreenRuntime state,Func<string,Task<RunApiHttpResponse>> control){foreach(var path in new[]{"loadout-enable","departure-enable","shop-enable"})Assert.That((await control(path)).StatusCode,Is.EqualTo(200));await state.RefreshSharedAsync();await state.RefreshTrainLoadoutAsync();var ids=new[]{"op_kyle","op_reina","op_eve","op_sera","op_mira"};for(int i=0;i<5;i++)state.Formation.Select(i,ids[i]);await state.Formation.SaveAsync();await state.Formation.ActivateAsync();state.SelectTrainCarriage(0,"car_combat");state.SelectTrainCarriage(1,"car_gun");await state.SaveTrainLoadoutAsync();await state.PreviewDepartureAsync(DepartureContract.Operations[0],"I");Assert.That(state.Departure,Is.Not.Null,state.ActionNotice);Assert.That((await control("combat-old-run")).StatusCode,Is.EqualTo(200));}
 [Test,Explicit("Pinned7ad482c finish/claim protocol on a historical memory-only run; no combat simulation or gate bypass.")]
 public async Task ActualNativeResultFinishReplayExplicitClaimLostReceiptAndRestart(){
  var(wire,session)=await Setup();Func<string,Task<RunApiHttpResponse>> control=path=>wire.SendAsync(GameApiBearerAuthRequestFactory.WithBearerToken(new RunApiHttpRequest("POST","/__fixture/"+path,null,null),session.AccessToken));using var state=new AccountScreenRuntime(wire,new Journal(),()=>session,()=>1);await PrepareResultFixture(state,control);var port=TestSecurePort();var journal=new EncryptedRunOperationJournal(port);using var runs=new DurableRunClient(new GameApiAuthenticatedHttpTransport(wire),journal,()=>session,()=>1,()=>new AppBuildSnapshot("1",100));state.BindRunRecovery(runs);var finish=SavedFixtureFinish("run_old");var original=PendingRunOperation.Finish(session.AccountId,finish,new AppBuildSnapshot("1",100),DateTimeOffset.UtcNow);Assert.That(await journal.PutAsync(original),Is.True);await runs.RestoreAsync();
  var root=new GameObject("ResultRecoveryHttpUi",typeof(RectTransform));((RectTransform)root.transform).sizeDelta=new Vector2(720,1280);var safe=new GameObject("SafeArea",typeof(RectTransform));safe.transform.SetParent(root.transform,false);var rect=(RectTransform)safe.transform;rect.anchorMin=Vector2.zero;rect.anchorMax=Vector2.one;rect.sizeDelta=Vector2.zero;
  try{var deck=LobbyCommandDeck.Attach(root,UnityEditor.AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/_LASTRAIL/UI/StartupResources/BootstrapFont.asset"),"LOCAL HTTP",1,new MissionShellMissionRowState[0],null,null);deck.BindAccount(state);deck.OpenRunLifecycle("run_old");while(state.RunResultsLoading)await Task.Yield();Assert.That((int)JObject.Parse((await control("result-metrics")).BodyJson)["finishes"],Is.Zero);Assert.That(root.GetComponentsInChildren<Button>().Single(b=>b.name=="ClaimRunReward").interactable,Is.False);
   wire.LoseDeparture="/v1/runs/run_old/finish";root.GetComponentsInChildren<Button>().Single(b=>b.name=="RecoverRunFinish").onClick.Invoke();while(state.Busy||state.RunResultsLoading)await Task.Yield();Assert.That(state.SavedFinish("run_old").AcceptedResponseJson,Is.Null);Assert.That(state.RunRewardPreview,Is.Not.Null,state.RunResultNotice);Assert.That((int)JObject.Parse((await control("result-metrics")).BodyJson)["claims"],Is.Zero);
   root.GetComponentsInChildren<Button>().Single(b=>b.name=="RecoverRunFinish").onClick.Invoke();while(state.Busy||state.RunResultsLoading)await Task.Yield();var completed=state.SavedFinish("run_old");Assert.That(completed.AcceptedResponseJson,Is.Not.Null,state.RunResultNotice);var response=JObject.Parse(completed.AcceptedResponseJson);Assert.That((bool)response["accepted"],Is.False);Assert.That((string)response["resultStatus"],Is.EqualTo("DUPLICATE_REPLAY"));Assert.That((string)response["rewardPreviewId"],Is.EqualTo(state.Lifecycle.PreviewId));Assert.That(wire.Requests.Where(r=>r.EndpointPath=="/v1/runs/run_old/finish").All(r=>r.BodyJson==finish.BodyJson&&Key(r)==finish.IdempotencyKey),Is.True);typeof(AccountScreenIntegrationTests).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{root,"ce03-reward-review-local-http.png"});
   var preview=state.Lifecycle.PreviewId;wire.LoseDeparture="/v1/runs/run_old/reward-preview/"+preview+"/claim";root.GetComponentsInChildren<Button>().Single(b=>b.name=="ClaimRunReward").onClick.Invoke();while(state.Busy||state.RunResultsLoading)await Task.Yield();var claim=state.SavedRewardClaim("run_old");Assert.That(claim,Is.Not.Null);Assert.That(claim.AcceptedResponseJson,Is.Null);Assert.That(state.Lifecycle.RewardStatus,Is.EqualTo("CLAIMED"));root.GetComponentsInChildren<Button>().Single(b=>b.name=="ClaimRunReward").onClick.Invoke();while(state.Busy||state.RunResultsLoading)await Task.Yield();claim=state.SavedRewardClaim("run_old");Assert.That(claim.AcceptedResponseJson,Is.Not.Null);Assert.That((string)JObject.Parse(claim.AcceptedResponseJson)["status"],Is.EqualTo("DUPLICATE_REPLAY"));Assert.That(JObject.Parse(claim.AcceptedResponseJson)["rewardLines"].Count(),Is.Zero);Assert.That(state.Lifecycle.TransactionReceipt["rewardPlan"]["rewardLines"].Count(),Is.GreaterThan(0));Assert.That(wire.Requests.Where(r=>r.EndpointPath.EndsWith("/claim")&&r.EndpointPath.Contains("/reward-preview/")).All(r=>Key(r)==claim.IdempotencyKey&&r.BodyJson==claim.BodyJson),Is.True);await state.RefreshSharedAsync();typeof(AccountScreenIntegrationTests).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{root,"ce03-reward-receipt-local-http.png"});
   root.GetComponentsInChildren<Button>().Single(b=>b.name=="CloseLobbyDialog").onClick.Invoke();Assert.That((await journal.ReadAsync(session.AccountId)).Count,Is.EqualTo(2));using var restarted=new DurableRunClient(new GameApiAuthenticatedHttpTransport(wire),new EncryptedRunOperationJournal(port),()=>session,()=>1);await restarted.RestoreAsync();Assert.That(restarted.Operations.Single(o=>o.Kind==PendingRunKind.Claim).AcceptedResponseJson,Is.EqualTo(claim.AcceptedResponseJson));var metrics=JObject.Parse((await control("result-metrics")).BodyJson);Assert.That((int)metrics["claims"],Is.EqualTo(1));Assert.That((int)metrics["finishes"],Is.EqualTo(1));Assert.That(state.CanConfirmDeparture,Is.False);
  }finally{UnityEngine.Object.DestroyImmediate(root);}
 }
 [Test,Explicit("Pinned7ad482c expired preview must allow UI return without automatic claim or clearing journals.")]
 public async Task ActualResultExpiryAndAccountSwitchKeepRecoveryRecords(){var(wire,session)=await Setup();Func<string,Task<RunApiHttpResponse>> control=path=>wire.SendAsync(GameApiBearerAuthRequestFactory.WithBearerToken(new RunApiHttpRequest("POST","/__fixture/"+path,null,null),session.AccessToken));long generation=1;using var state=new AccountScreenRuntime(wire,new Journal(),()=>session,()=>generation);await PrepareResultFixture(state,control);var journal=new EncryptedRunOperationJournal(TestSecurePort());using var runs=new DurableRunClient(new GameApiAuthenticatedHttpTransport(wire),journal,()=>session,()=>generation,()=>new AppBuildSnapshot("1",100));state.BindRunRecovery(runs);var result=await runs.FinishAsync(SavedFixtureFinish("run_old"));Assert.That(result,Is.Not.Null,runs.Notice);await state.ReadRunResultsAsync("run_old");Assert.That(state.CanClaimRunReward("run_old"),Is.True);await control("expire-run-reward");await state.ReadRunResultsAsync("run_old");Assert.That(state.Lifecycle.Disposition,Is.EqualTo("EXPIRED_UNCLAIMED"));Assert.That(state.CanClaimRunReward("run_old"),Is.False);Assert.That(state.Lifecycle.UiReturnAllowed,Is.True);generation++;state.SynchronizeSession();await state.ClaimRunRewardAsync("run_old");Assert.That((int)JObject.Parse((await control("result-metrics")).BodyJson)["claims"],Is.Zero);Assert.That((await journal.ReadAsync(session.AccountId)).Count,Is.EqualTo(1));}
} }

